const parseMapCamelot = (k) => {
  if (!k) return null;
  const m = String(k).trim().toUpperCase().match(/^(1[0-2]|[1-9])([AB])$/);
  if (!m) return null;
  return { num: parseInt(m[1], 10), letter: m[2], full: `${m[1]}${m[2]}` };
};
